import{X as e,Y as t,ct as n,t as r}from"./chunks/framework.CaFWb3SA.js";var i=JSON.parse(`{"title":"数值与文本","description":"","frontmatter":{},"headers":[],"relativePath":"guide/tutorials/Type.md","filePath":"guide/tutorials/Type.md"}`),a={name:`guide/tutorials/Type.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="数值与文本" tabindex="-1">数值与文本 <a class="header-anchor" href="#数值与文本" aria-label="Permalink to “数值与文本”">​</a></h1><h2 id="前言与确认" tabindex="-1">前言与确认 <a class="header-anchor" href="#前言与确认" aria-label="Permalink to “前言与确认”">​</a></h2><p>前面，我们已经学过了变量。如果说有什么需要复习的话，那么实际只有一句话：</p><blockquote><p>变量由两部分组成，变量名和值。</p></blockquote><p>仅此而已。但关于<strong>值</strong>，我们有一些话要说。</p><div class="warning custom-block"><p class="custom-block-title">教程依赖</p><p>本教程假设您已学习过<a href="./../Quick_Start.html">快速开始</a>和<a href="./Variable.html">常量与变量</a>。若您尚未学习过，我们强烈推荐您首先学习相应教程。</p></div><p>先确认一下我们现有的工程文件夹结构：</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span>root/</span></span>
<span class="line"><span> ├─ emuera.config</span></span>
<span class="line"><span> ├─ Emuera1824.exe</span></span>
<span class="line"><span> ├─ CSV/</span></span>
<span class="line"><span> └─ ERB/</span></span>
<span class="line"><span>     └─ System.erb</span></span></code></pre></div><p>其中，<code>System.erb</code>的代码为：</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#E6E6E6;">@</span><span style="color:#DCDCAA;">EventFirst</span></span>
<span class="line"><span style="color:#569CD6;">  Print</span><span style="color:#9CDCFE;"> Hello</span><span style="color:#9CDCFE;"> World</span><span style="color:#D4D4D4;">!</span></span>
<span class="line"><span style="color:#569CD6;">  Quit</span></span></code></pre></div><h2 id="两种值-数值与字符串" tabindex="-1">两种值：数值与字符串 <a class="header-anchor" href="#两种值-数值与字符串" aria-label="Permalink to “两种值：数值与字符串”">​</a></h2><p>在 EraBasic 中，<strong>值</strong>的类型大致有两种：<strong>数值</strong>和<strong>字符串</strong>。</p><ul><li><strong>数值</strong>：就是数学里的数，比如 <code>1</code>、<code>100</code>、<code>-5</code>；</li><li><strong>字符串</strong>：其实就是<strong>文本</strong>啦，比如 <code>Hello World!</code>、<code>小明</code>。</li></ul><p>字符串的英文是 String，缩写是 <strong>S</strong>。这很重要，得牢记：以后凡是看到命令或变量名里带一个 <code>S</code>，多半都和<strong>文本</strong>有关。</p><p>前面学到的变量定义 <code>#Dim</code> 语句，定义的是<strong>数值</strong>变量。在后面加个 <strong>S</strong>，就变成定义字符串变量了：</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#E6E6E6;">@</span><span style="color:#DCDCAA;">EventFirst</span></span>
<span class="line"><span style="color:#569CD6;">#</span><span style="color:#C586C0;">DimS</span><span style="color:#9CDCFE;"> Text</span><span style="color:#D4D4D4;"> =</span><span style="color:#CE9178;"> &quot;Hello World!&quot;</span></span>
<span class="line"><span style="color:#569CD6;">  Quit</span></span></code></pre></div><p>注意，字符串的<strong>值必须用双引号 <code>&quot;</code> 括起来</strong>，而数值不用。引号就像贴在文字上的标签，告诉引擎：“这一段是文本，不要当成命令处理。”</p><h2 id="数值-能算数的值" tabindex="-1">数值：能算数的值 <a class="header-anchor" href="#数值-能算数的值" aria-label="Permalink to “数值：能算数的值”">​</a></h2><p><code>#Dim</code> 定义的变量里装的是数值，可以直接参与加减乘除：</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#E6E6E6;">@</span><span style="color:#DCDCAA;">EventFirst</span></span>
<span class="line"><span style="color:#569CD6;">  #</span><span style="color:#C586C0;">Dim</span><span style="color:#9CDCFE;"> Stone</span><span style="color:#D4D4D4;"> =</span><span style="color:#B5CEA8;"> 3</span></span>
<span class="line"><span style="color:#569CD6;">  #</span><span style="color:#C586C0;">Dim</span><span style="color:#9CDCFE;"> Apple</span><span style="color:#D4D4D4;"> =</span><span style="color:#B5CEA8;"> 2</span></span>
<span class="line"><span style="color:#9CDCFE;">  Stone</span><span style="color:#D4D4D4;"> =</span><span style="color:#9CDCFE;"> Stone</span><span style="color:#D4D4D4;"> +</span><span style="color:#9CDCFE;"> Apple</span></span>
<span class="line"><span style="color:#569CD6;">  PrintV</span><span style="color:#9CDCFE;"> Stone</span></span>
<span class="line"><span style="color:#569CD6;">  Quit</span></span></code></pre></div><p>输出：</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span>5</span></span></code></pre></div><p>关于数值，有两件事现在知道就好：</p><ul><li>EraBasic 的数值是 <strong>64 位整数</strong>，也就是说<strong>没有小数</strong>。<code>5 / 3</code> 的结果是 <code>1</code>，而不是 <code>1.666...</code>（这叫“整除”）；</li><li>能表示的范围非常大（约 ±9.2×10¹⁸），做游戏基本不用担心装不下。</li></ul><h2 id="字符串-只能拼接的值" tabindex="-1">字符串：只能拼接的值 <a class="header-anchor" href="#字符串-只能拼接的值" aria-label="Permalink to “字符串：只能拼接的值”">​</a></h2><p><code>#DimS</code> 定义的字符串变量里装的是文本。文本不能做加减乘除，但可以用 <code>+</code> 把它们<strong>拼接</strong>起来：</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#E6E6E6;">@</span><span style="color:#DCDCAA;">EventFirst</span></span>
<span class="line"><span style="color:#569CD6;">  #</span><span style="color:#C586C0;">DimS</span><span style="color:#9CDCFE;"> Name</span><span style="color:#D4D4D4;"> =</span><span style="color:#CE9178;"> &quot;小明&quot;</span></span>
<span class="line"><span style="color:#569CD6;">  #</span><span style="color:#C586C0;">DimS</span><span style="color:#9CDCFE;"> Greeting</span><span style="color:#D4D4D4;"> =</span><span style="color:#CE9178;"> &quot;你好，&quot;</span></span>
<span class="line"><span style="color:#9CDCFE;">  Greeting</span><span style="color:#D4D4D4;"> =</span><span style="color:#9CDCFE;"> Greeting</span><span style="color:#D4D4D4;"> +</span><span style="color:#9CDCFE;"> Name</span></span>
<span class="line"><span style="color:#569CD6;">  PrintS</span><span style="color:#9CDCFE;"> Greeting</span></span>
<span class="line"><span style="color:#569CD6;">  Quit</span></span></code></pre></div><p>输出：</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span>你好，小明</span></span></code></pre></div><h2 id="怎么把值打印出来" tabindex="-1">怎么把值打印出来？ <a class="header-anchor" href="#怎么把值打印出来" aria-label="Permalink to “怎么把值打印出来？”">​</a></h2><p>我们现在见过三个“打印”命令，是时候把它们摆在一起对比了：</p><table tabindex="0"><thead><tr><th>命令</th><th>用途</th><th>例子</th><th>输出</th></tr></thead><tbody><tr><td><code>Print</code></td><td>原样输出后面的文本</td><td><code>Print Hello</code></td><td><code>Hello</code></td></tr><tr><td><code>PrintV</code></td><td>输出一个<strong>数值</strong>变量</td><td><code>PrintV Stone</code></td><td>变量里的数值</td></tr><tr><td><code>PrintS</code></td><td>输出一个<strong>字符串</strong>变量</td><td><code>PrintS Name</code></td><td>变量里的文本</td></tr></tbody></table><p>最容易混淆的是 <code>Print</code> 和 <code>PrintS</code>：</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#569CD6;">#</span><span style="color:#C586C0;">DimS</span><span style="color:#9CDCFE;"> Text</span><span style="color:#D4D4D4;"> =</span><span style="color:#CE9178;"> &quot;Hello World!&quot;</span></span>
<span class="line"><span style="color:#569CD6;">Print</span><span style="color:#9CDCFE;"> Text</span></span>
<span class="line"><span style="color:#569CD6;">PrintS</span><span style="color:#9CDCFE;"> Text</span></span></code></pre></div><p>第一行会把 <code>Text</code> 这两个字原样打印出来（因为它只是一段普通文本），第二行才会打印变量里的 <code>Hello World!</code>。</p><p>一句话总结：<strong><code>Print</code> 打印字面文本，<code>PrintV</code>/<code>PrintS</code> 打印变量里的值。</strong></p><h2 id="常见错误" tabindex="-1">常见错误 <a class="header-anchor" href="#常见错误" aria-label="Permalink to “常见错误”">​</a></h2><p>数值和字符串是“两种不同的东西”，不能混着用。比如把文本直接塞进数值变量：</p><div class="warning custom-block"><p class="custom-block-title">该代码含有可期待的错误</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#E6E6E6;">@</span><span style="color:#DCDCAA;">EventFirst</span></span>
<span class="line"><span style="color:#569CD6;">  #</span><span style="color:#C586C0;">Dim</span><span style="color:#9CDCFE;"> Stone</span><span style="color:#D4D4D4;"> =</span><span style="color:#CE9178;"> &quot;三&quot;</span></span>
<span class="line"><span style="color:#569CD6;">  Quit</span></span></code></pre></div></div><p>会得到报错：</p><div class="danger custom-block"><p class="custom-block-title">错误信息<a href="javascript:alert(&#39;TODO&#39;)">索引</a></p><blockquote><p>&#39;=&#39;の前後で型が一致しません</p></blockquote><p><code>=</code> 的前后类型不一致。</p></div><p>想给字符串变量赋值，记得把 <code>#Dim</code> 换成 <code>#DimS</code>，并把值用双引号括起来。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to “小结”">​</a></h2><ul><li>值分两种：<strong>数值</strong>和<strong>字符串（文本）</strong>；</li><li><code>#Dim</code> 定义数值变量，<code>#DimS</code> 定义字符串变量；</li><li>字符串的值要用双引号括起来；</li><li>数值能算数，字符串能拼接；</li><li><code>Print</code> 打印字面文本，<code>PrintV</code> 打印数值变量，<code>PrintS</code> 打印字符串变量。</li></ul><p>下一步，我们来学习怎么让游戏<strong>接受玩家的输入</strong>：<a href="./IO.html">输入与输出</a>。</p>`,45)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};